def min_xor_path(edges):
    n = len(edges)
    graph = [[] for _ in range(n)]

    # Build the graph
    for u, v, w in edges:
        graph[u - 1].append((v - 1, w))
        graph[v - 1].append((u - 1, w))

    def dfs(u, parent, xor_value):
        if u == n - 1:
            return xor_value

        min_xor = float('inf')
        for v, w in graph[u]:
            if v != parent:
                new_xor = xor_value ^ w
                min_xor = min(min_xor, dfs(v, u, new_xor))

        return min_xor

    return dfs(0, None, 0)

# Example usage
edges = [
    (1, 2, 3),
    (2, 4, 5),
    (1, 3, 4),
    (3, 4, 7)
]
print(min_xor_path(edges))  # Output: 3
